[asy]
unitsize(0.4 cm);

pair Z = interp((0,5),(12,0),0.6);
pair P = ((0,0) + reflect((12,0),(0,5))*(0,0))/2;

draw((12,0)--(0,5),red);
draw((-1,0)--(13,0));
draw((0,-1)--(0,6));
draw((0,0)--Z);
draw((0,0)--P);
draw(rightanglemark((0,0),P,(12,0),20));

dot("$12$", (12,0), S);
dot("$5i$", (0,5), W);
dot("$z$", Z, NE);

label("$h$", P/2, SE);
[/asy]

